import { create, fromBinary, toBinary } from "@bufbuild/protobuf"
import {
  Direction,
  FrameType,
  RelayEnvelopeSchema,
} from "../../../../../contracts/generated/relay/typescript/ji/relay/v1/relay_pb"

export const RELAY_RELEASE_VERSION = "0.1.0"

export type RelayRoute = { tenantId: string; routeId: string; hostId: string; deviceId: string }

export function connectRelay(
  url: string,
  route: RelayRoute,
  onFrame: (frame: Uint8Array, counter: bigint, keyEpoch: bigint) => void,
): { send: (frame: Uint8Array, counter: bigint, keyEpoch: bigint) => void; close: () => void } {
  const socket = new WebSocket(url)
  socket.binaryType = "arraybuffer"
  const connectionId = crypto.randomUUID()
  socket.onmessage = message => {
    if (!(message.data instanceof ArrayBuffer)) { socket.close(1003, "binary Relay frames required"); return }
    const envelope = fromBinary(RelayEnvelopeSchema, new Uint8Array(message.data))
    if (envelope.releaseVersion !== RELAY_RELEASE_VERSION || envelope.connectionId !== connectionId
      || envelope.tenantId !== route.tenantId || envelope.routeId !== route.routeId
      || envelope.hostId !== route.hostId || envelope.deviceId !== route.deviceId
      || envelope.direction !== Direction.HOST_TO_CLIENT) {
      socket.close(1008, "Relay identity changed")
      return
    }
    onFrame(envelope.opaquePayload, envelope.counter, envelope.keyEpoch)
  }
  const send = (frame: Uint8Array, counter: bigint, keyEpoch: bigint) => {
    if (socket.readyState !== WebSocket.OPEN) throw new Error("Relay connection is not ready")
    socket.send(toBinary(RelayEnvelopeSchema, create(RelayEnvelopeSchema, {
      releaseVersion: RELAY_RELEASE_VERSION,
      connectionId,
      tenantId: route.tenantId,
      routeId: route.routeId,
      hostId: route.hostId,
      deviceId: route.deviceId,
      direction: Direction.CLIENT_TO_HOST,
      frameType: FrameType.NOISE_TRANSPORT,
      counter,
      keyEpoch,
      opaquePayload: frame,
    })))
  }
  return { send, close: () => socket.close(1000, "client closed") }
}
